// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ─────────────────────────────────────────────────────────
   box wireframe      → LineSegments(EdgesGeometry(BoxGeometry(4,8,4)))  black
   3 interior layers  → Mesh(PlaneGeometry(4,4), rotX -PI/2) fill #e6e6e6 a.55
   layer outlines     → LineLoop 4 corners  #6b6b6b
   5 dotted paths     → Line(BufferGeometry, LineDashedMaterial) dark grey
   5 start dots       → SphereGeometry(0.09)  black (3) / grey (2)
   5 path arrowheads  → ConeGeometry(0.09,0.28) oriented to curve tangent
   left  side arrow   → Cylinder shaft + Cone cap at TOP    black
   right side arrow   → Cylinder shaft + Cone cap at BOTTOM black
   5 moving markers   → SphereGeometry(0.12)  blue accent
   labels             → addLabel HTML (2 rotated 90°)
─────────────────────────────────────────────────────────────────────────── */

const BOX_W = 4, BOX_H = 8;
const LAYER_Y = [-1.6, 0.0, 1.6];
const STEP_Y  = [-4, -1.6, 0.0, 1.6, 4];

const root = new THREE.Group();
scene.add(root);

/* ── box wireframe ──────────────────────────────────────────────────────── */
const boxEdges = new THREE.LineSegments(
  new THREE.EdgesGeometry(new THREE.BoxGeometry(BOX_W, BOX_H, BOX_W)),
  new THREE.LineBasicMaterial({ color: 0x000000 })
);
boxEdges.renderOrder = 3;
root.add(boxEdges);
registerInteractive(boxEdges, {
  title: 'The network as a volume',
  tooltip: 'Data face at the bottom, embedding face at the top',
  body: 'The tall box is one architecture. Its bottom square face is the data space, its top square face is the embedding space, and the interior planes are intermediate layers.'
});

/* ── interior layer planes ──────────────────────────────────────────────── */
const planes = [];
const planeOutlines = [];
LAYER_Y.forEach((y, i) => {
  const g = new THREE.PlaneGeometry(BOX_W, BOX_W);
  g.rotateX(-Math.PI / 2);
  const m = new THREE.MeshBasicMaterial({
    color: 0xe6e6e6, transparent: true, opacity: 0.55,
    depthWrite: false, side: THREE.DoubleSide
  });
  const mesh = new THREE.Mesh(g, m);
  mesh.position.y = y;
  mesh.renderOrder = 2;
  root.add(mesh);
  planes.push(mesh);

  const h = BOX_W / 2;
  const pts = [
    new THREE.Vector3(-h, y, -h), new THREE.Vector3(h, y, -h),
    new THREE.Vector3(h, y, h), new THREE.Vector3(-h, y, h)
  ];
  const ol = new THREE.LineLoop(
    new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineBasicMaterial({ color: 0x6b6b6b })
  );
  ol.renderOrder = 4;
  root.add(ol);
  planeOutlines.push(ol);

  registerInteractive(mesh, {
    title: 'Intermediate layer ' + (i + 1),
    tooltip: 'Layer ' + (i + 1) + ' — a re-expression of the same points',
    body: 'Every datapoint has a location on this plane. Depth, not dimensionality, is what changes the representation from one plane to the next.'
  });
});

/* ── the five paths ─────────────────────────────────────────────────────── */
const W = 5.5;
const defs = [
  { x0: -1.2, z0: -0.4, y0: -3.0, col: 0x111111, dx: -0.45, dz: -0.30, ax: 0.24, az: 0.22, p1: 0.4, p2: 1.1 },
  { x0: -0.1, z0: -1.0, y0: -3.4, col: 0x111111, dx: -0.30, dz: 0.45, ax: 0.22, az: 0.24, p1: 2.0, p2: 0.2 },
  { x0: 1.30, z0: -0.8, y0: -3.3, col: 0x111111, dx: 0.25, dz: 0.35, ax: 0.22, az: 0.22, p1: 3.1, p2: 2.4 },
  { x0: -0.4, z0: 0.90, y0: -1.6, col: 0x6a6a6a, dx: -0.40, dz: -0.45, ax: 0.22, az: 0.24, p1: 1.2, p2: 3.0 },
  { x0: 0.90, z0: 0.50, y0: -1.6, col: 0x6a6a6a, dx: 0.45, dz: -0.30, ax: 0.24, az: 0.22, p1: 0.8, p2: 1.8 }
];
const CL = 1.85;
function u0of(d) { return (d.y0 + 4) / 8; }
function pathPoint(d, u, out) {
  const u0 = u0of(d);
  let x = d.x0 + d.dx * (u - u0) + d.ax * (Math.sin(W * u + d.p1) - Math.sin(W * u0 + d.p1));
  let z = d.z0 + d.dz * (u - u0) + d.az * (Math.cos(W * u + d.p2) - Math.cos(W * u0 + d.p2));
  x = THREE.MathUtils.clamp(x, -CL, CL);
  z = THREE.MathUtils.clamp(z, -CL, CL);
  return (out || new THREE.Vector3()).set(x, -4 + 8 * u, z);
}
function pathTangent(d, u) {
  const a = pathPoint(d, Math.max(0, u - 0.01));
  const b = pathPoint(d, Math.min(1, u + 0.01));
  return b.sub(a).normalize();
}

const U_END = (3.4 + 4) / 8;
const upHeads = [], downHeads = [], markers = [];

defs.forEach((d, i) => {
  const u0 = u0of(d);
  const pts = [];
  for (let k = 0; k <= 140; k++) pts.push(pathPoint(d, u0 + (U_END - u0) * (k / 140)));

  const line = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(pts),
    new THREE.LineDashedMaterial({ color: 0x2b2b2b, dashSize: 0.07, gapSize: 0.09 })
  );
  line.computeLineDistances();
  line.renderOrder = 5;
  root.add(line);
  registerInteractive(line, {
    title: 'Path of one datapoint',
    tooltip: 'One point traced through every layer',
    body: 'The dotted curve is a single datapoint tracked through the stack. Read upward it is representation learning; read downward it is generative modeling.'
  });

  // start dot
  const dot = new THREE.Mesh(
    new THREE.SphereGeometry(0.09, 16, 12),
    new THREE.MeshBasicMaterial({ color: d.col })
  );
  dot.position.copy(pathPoint(d, u0));
  dot.renderOrder = 6;
  root.add(dot);

  // arrowhead at top (up reading)
  const headUp = new THREE.Mesh(
    new THREE.ConeGeometry(0.09, 0.28, 14),
    new THREE.MeshBasicMaterial({ color: 0x2b2b2b })
  );
  const tEnd = pathTangent(d, U_END);
  headUp.position.copy(pathPoint(d, U_END));
  headUp.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tEnd);
  headUp.renderOrder = 6;
  root.add(headUp);
  upHeads.push(headUp);

  // arrowhead at bottom (down reading)
  const headDn = new THREE.Mesh(
    new THREE.ConeGeometry(0.09, 0.28, 14),
    new THREE.MeshBasicMaterial({ color: 0x2b2b2b })
  );
  const tStart = pathTangent(d, u0).negate();
  headDn.position.copy(pathPoint(d, u0)).addScaledVector(tStart, 0.1);
  headDn.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tStart);
  headDn.visible = false;
  headDn.renderOrder = 6;
  root.add(headDn);
  downHeads.push(headDn);

  // moving / layer marker
  const mk = new THREE.Mesh(
    new THREE.SphereGeometry(0.12, 18, 14),
    new THREE.MeshBasicMaterial({ color: 0x1a73e8 })
  );
  mk.renderOrder = 7;
  root.add(mk);
  markers.push(mk);
});

/* ── side arrows ────────────────────────────────────────────────────────── */
function makeSideArrow(x, z, dir) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color: 0x000000 });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 7.3, 10), mat);
  shaft.position.set(x, dir > 0 ? -0.25 : 0.25, z);
  g.add(shaft);
  const cap = new THREE.Mesh(new THREE.ConeGeometry(0.14, 0.45, 16), mat);
  cap.position.set(x, dir > 0 ? 3.7 : -3.7, z);
  if (dir < 0) cap.rotation.z = Math.PI;
  g.add(cap);
  g.userData.mat = mat;
  root.add(g);
  return g;
}
const leftArrow = makeSideArrow(-3.2, 3.2, +1);
const rightArrow = makeSideArrow(3.2, -3.2, -1);

/* ── camera ─────────────────────────────────────────────────────────────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  heightFraction: 0.72
});
controls.minPolarAngle = 0.35;
controls.maxPolarAngle = 1.45;

/* ── labels ─────────────────────────────────────────────────────────────── */
const SERIF = 'font-family:Georgia,\'Times New Roman\',serif';
addLabel(`<span style="${SERIF}">Embedding</span>`, new THREE.Vector3(0, 6.3, 0),
  { fontSize: '22px', offset: [0, -6] });
addLabel(`<span style="${SERIF}">Data</span>`, new THREE.Vector3(0, -6.4, 0),
  { fontSize: '22px', offset: [0, 10] });

const labLeft = addLabel(
  `<span style="display:inline-block;transform:rotate(-90deg);${SERIF}">Representation learning</span>`,
  new THREE.Vector3(-4.2, 0, 4.2), { fontSize: '19px' });
const labRight = addLabel(
  `<span style="display:inline-block;transform:rotate(-90deg);${SERIF}">Generative modeling</span>`,
  new THREE.Vector3(4.2, 0, -4.2), { fontSize: '19px' });

/* ── state ──────────────────────────────────────────────────────────────── */
let direction = 'up';       // 'up' | 'down'
let layerIndex = 0;         // 0..4
let flowOn = false;
let curU = (STEP_Y[0] + 4) / 8;
let targetU = curU;
let phase = 0;

function applyDirection() {
  upHeads.forEach(h => h.visible = direction === 'up');
  downHeads.forEach(h => h.visible = direction === 'down');
  const active = 0x000000, dim = 0xb4b4b4;
  leftArrow.userData.mat.color.setHex(direction === 'up' ? active : dim);
  rightArrow.userData.mat.color.setHex(direction === 'down' ? active : dim);
  labLeft.div.style.color = direction === 'up' ? '#000' : '#b4b4b4';
  labRight.div.style.color = direction === 'down' ? '#000' : '#b4b4b4';
  document.getElementById('dirUp').classList.toggle('active', direction === 'up');
  document.getElementById('dirDown').classList.toggle('active', direction === 'down');
}

function applyLayer() {
  targetU = (STEP_Y[layerIndex] + 4) / 8;
  planes.forEach((p, i) => {
    const act = (layerIndex - 1) === i;
    p.material.opacity = act ? 0.8 : 0.55;
    p.material.color.setHex(act ? 0xd8d8d8 : 0xe6e6e6);
    planeOutlines[i].material.color.setHex(act ? 0x111111 : 0x6b6b6b);
  });
  for (let i = 0; i < 5; i++) {
    document.getElementById('lay' + i).classList.toggle('active', i === layerIndex);
  }
}

document.getElementById('dirUp').onclick = () => { direction = 'up'; applyDirection(); };
document.getElementById('dirDown').onclick = () => { direction = 'down'; applyDirection(); };
for (let i = 0; i < 5; i++) {
  document.getElementById('lay' + i).onclick = () => { layerIndex = i; applyLayer(); };
}
const btnFlow = document.getElementById('btnFlow');
btnFlow.onclick = () => {
  flowOn = !flowOn;
  btnFlow.classList.toggle('active', flowOn);
  btnFlow.textContent = flowOn ? '❚❚ Pause flow' : '▶ Animate points along the paths';
};

/* ── guided tour ────────────────────────────────────────────────────────── */
const steps = [
  { t: 'The data space', n: 'Five datapoints sit on the bottom face of the box — the raw data space, labeled “Data”. Nothing has been transformed yet.', d: 'up', l: 0 },
  { t: 'Into the first layer', n: 'Stepping up one plane, each point is re-placed on the first intermediate layer. The dotted curves show where each one went.', d: 'up', l: 1 },
  { t: 'Deeper layers reshape the points', n: 'By the third plane the points have moved relative to one another — depth is what changes the representation, not the dimensionality of the box.', d: 'up', l: 3 },
  { t: 'The embedding', n: 'The arrowheads reach the top face: this is the embedding. Read bottom-up, the whole stack is representation learning.', d: 'up', l: 4 },
  { t: 'Flip the reading', n: 'Toggle to generative modeling: the arrows reverse and the same paths now carry points downward from the embedding into data. One architecture, two readings.', d: 'down', l: 4 },
  { t: 'Generating back down to data', n: 'Stepping back down to the bottom face produces samples in data space — which raises the question of what really distinguishes data from an embedding.', d: 'down', l: 0 }
];
let stepIdx = -1;
function goToStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  const s = steps[stepIdx];
  direction = s.d; layerIndex = s.l;
  applyDirection(); applyLayer();
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + s.t;
  document.getElementById('stepText').textContent = s.n;
}
document.getElementById('btnNext').onclick = () => goToStep(stepIdx + 1);
document.getElementById('btnPrev').onclick = () => goToStep(stepIdx - 1);

applyDirection();
applyLayer();
goToStep(0);

/* ── update loop (geometry only; scaffold owns rendering) ───────────────── */
const _tmp = new THREE.Vector3();
let _prev = performance.now();
(function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(3, Math.max(0.4, (now - _prev) / 16));
  _prev = now;

  if (flowOn) {
    phase = (phase + 0.0035 * dt) % 1;
    for (let i = 0; i < defs.length; i++) {
      let u = (phase + i * 0.08) % 1;
      if (direction === 'down') u = 1 - u;
      markers[i].position.copy(pathPoint(defs[i], u, _tmp));
      markers[i].visible = true;
    }
  } else {
    curU += (targetU - curU) * Math.min(1, 0.12 * dt);
    for (let i = 0; i < defs.length; i++) {
      markers[i].position.copy(pathPoint(defs[i], curU, _tmp));
      markers[i].visible = true;
    }
  }
})();
