  headUp.position.copy(pathPoint(d, U_END)).addScaledVector(tEnd, 0.14);
  headUp.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tEnd);
  headUp.renderOrder = 6;
  root.add(headUp);
  upHeads.push(headUp);

  // arrowhead at bottom of curve (down reading)
  const headDn = new THREE.Mesh(
    new THREE.ConeGeometry(0.115, 0.36, 16),
    new THREE.MeshBasicMaterial({ color: 0x1c1c1c })
  );
  const tStart = pathTangent(d, u0).negate();
  headDn.position.copy(pathPoint(d, u0)).addScaledVector(tStart, 0.16);
  headDn.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tStart);
  headDn.visible = false;
  headDn.renderOrder = 6;
  root.add(headDn);
  downHeads.push(headDn);

  // traversal / flow marker — monochrome, hidden in the default view
  const mk = new THREE.Mesh(
    new THREE.SphereGeometry(0.11, 18, 14),
    new THREE.MeshBasicMaterial({ color: 0x262626 })
  );
  mk.visible = false;
  mk.renderOrder = 7;
  root.add(mk);
  markers.push(mk);
});

/* ── side arrows (both full black, active one slightly heavier) ─────────── */
function makeSideArrow(x, z, dir) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color: 0x000000 });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.04, 7.3, 12), mat);
  shaft.position.set(x, dir > 0 ? -0.25 : 0.25, z);
  g.add(shaft);
  const cap = new THREE.Mesh(new THREE.ConeGeometry(0.15, 0.48, 18), mat);
  cap.position.set(x, dir > 0 ? 3.7 : -3.7, z);
  if (dir < 0) cap.rotation.z = Math.PI;
  g.add(cap);
  g.userData = { mat, shaft, cap };
  root.add(g);
  return g;
}
const leftArrow = makeSideArrow(-3.4, 3.4, +1);
const rightArrow = makeSideArrow(3.4, -3.4, -1);
registerInteractive(leftArrow.userData.shaft, {
  title: 'Representation learning',
  tooltip: 'Read the stack bottom-up',
  body: 'Reading the same stack from the data face upward maps each datapoint to an embedding: this is representation learning.'
});
registerInteractive(rightArrow.userData.shaft, {
  title: 'Generative modeling',
  tooltip: 'Read the stack top-down',
  body: 'Reading the identical stack from the embedding face downward turns a code into a sample in data space: this is generative modeling.'
});

/* ── camera ─────────────────────────────────────────────────────────────── */
setCameraView({
  projection: 'orthographic',
  axisScreenAngles: { x: 30, z: 30 },
  heightFraction: 0.82
});
controls.minPolarAngle = 0.35;
controls.maxPolarAngle = 1.45;

/* ── labels ─────────────────────────────────────────────────────────────── */
const SERIF = 'font-family:Georgia,\'Times New Roman\',serif';
addLabel(`<span style="${SERIF}">Embedding</span>`, new THREE.Vector3(0, 6.35, 0),
  { fontSize: '23px', offset: [0, -6] });
addLabel(`<span style="${SERIF}">Data</span>`, new THREE.Vector3(0, -6.45, 0),
  { fontSize: '23px', offset: [0, 10] });

const labLeft = addLabel(
  `<span id="txtL" style="display:inline-block;transform:rotate(-90deg);${SERIF}">Representation learning</span>`,
  new THREE.Vector3(-4.4, 0, 4.4), { fontSize: '19px' });
const labRight = addLabel(
  `<span id="txtR" style="display:inline-block;transform:rotate(-90deg);${SERIF}">Generative modeling</span>`,
  new THREE.Vector3(4.4, 0, -4.4), { fontSize: '19px' });
labLeft.div.style.color = '#000';
labRight.div.style.color = '#000';

/* ── state ──────────────────────────────────────────────────────────────── */
let direction = 'up';
let layerIndex = 0;
let flowOn = false;
let curU = (STEP_Y[0] + 4) / 8;
let targetU = curU;
let phase = 0;

function styleArrow(g, active) {
  g.userData.shaft.scale.set(active ? 1.35 : 0.85, 1, active ? 1.35 : 0.85);
  g.userData.cap.scale.setScalar(active ? 1.15 : 0.85);
}

function applyDirection() {
  upHeads.forEach(h => h.visible = direction === 'up');
  downHeads.forEach(h => h.visible = direction === 'down');
  styleArrow(leftArrow, direction === 'up');
  styleArrow(rightArrow, direction === 'down');
  const tL = document.getElementById('txtL'), tR = document.getElementById('txtR');
  if (tL) tL.style.fontWeight = direction === 'up' ? '700' : '400';
  if (tR) tR.style.fontWeight = direction === 'down' ? '700' : '400';
  document.getElementById('dirUp').classList.toggle('active', direction === 'up');
  document.getElementById('dirDown').classList.toggle('active', direction === 'down');
}

function applyLayer() {
  targetU = (STEP_Y[layerIndex] + 4) / 8;
  planes.forEach((p, i) => {
    const act = (layerIndex - 1) === i;
    p.material.opacity = act ? 0.8 : 0.55;
    p.material.color.setHex(act ? 0xd8d8d8 : 0xe6e6e6);
    planeOutlines[i].material.color.setHex(act ? 0x111111 : 0x6b6b6b);
  });
  for (let i = 0; i < 5; i++) {
    document.getElementById('lay' + i).classList.toggle('active', i === layerIndex);
  }
}

document.getElementById('dirUp').onclick = () => { direction = 'up'; applyDirection(); };
document.getElementById('dirDown').onclick = () => { direction = 'down'; applyDirection(); };
for (let i = 0; i < 5; i++) {
  document.getElementById('lay' + i).onclick = () => { layerIndex = i; applyLayer(); };
}
const btnFlow = document.getElementById('btnFlow');
btnFlow.onclick = () => {
  flowOn = !flowOn;
  btnFlow.classList.toggle('active', flowOn);
  btnFlow.textContent = flowOn ? '❚❚ Pause flow' : '▶ Animate points along the paths';
};

/* ── guided tour ────────────────────────────────────────────────────────── */
const steps = [
  { t: 'The data space', n: 'Five datapoints sit on the bottom face of the box — the raw data space, labeled “Data”. Nothing has been transformed yet.', d: 'up', l: 0 },
  { t: 'Into the first layer', n: 'Stepping up one plane, each point is re-placed on the first intermediate layer. The dotted curves show where each one went.', d: 'up', l: 1 },
  { t: 'Deeper layers reshape the points', n: 'By the third plane the points have moved relative to one another — depth is what changes the representation, not the dimensionality of the box.', d: 'up', l: 3 },
  { t: 'The embedding', n: 'The arrowheads reach the top face: this is the embedding. Read bottom-up, the whole stack is representation learning.', d: 'up', l: 4 },
  { t: 'Flip the reading', n: 'Toggle to generative modeling: the arrows reverse and the same paths now carry points downward from the embedding into data. One architecture, two readings.', d: 'down', l: 4 },
  { t: 'Generating back down to data', n: 'Stepping back down to the bottom face produces samples in data space — which raises the question of what really distinguishes data from an embedding.', d: 'down', l: 0 }
];
let stepIdx = -1;
function goToStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  const s = steps[stepIdx];
  direction = s.d; layerIndex = s.l;
  applyDirection(); applyLayer();
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + s.t;
  document.getElementById('stepText').textContent = s.n;
}
document.getElementById('btnNext').onclick = () => goToStep(stepIdx + 1);
document.getElementById('btnPrev').onclick = () => goToStep(stepIdx - 1);

applyDirection();
applyLayer();
goToStep(0);

/* ── update loop (geometry only; scaffold owns rendering) ───────────────── */
const _tmp = new THREE.Vector3();
let _prev = performance.now();
(function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(3, Math.max(0.4, (now - _prev) / 16));
  _prev = now;

  if (flowOn) {
    phase = (phase + 0.0035 * dt) % 1;
    for (let i = 0; i < defs.length; i++) {
      const d = defs[i], u0 = u0of(d);
      let f = (phase + i * 0.13) % 1;
      if (direction === 'down') f = 1 - f;
      markers[i].position.copy(pathPoint(d, u0 + (U_END - u0) * f, _tmp));
      markers[i].visible = true;
    }
  } else {
    curU += (targetU - curU) * Math.min(1, 0.12 * dt);
    const show = layerIndex !== 0;
    for (let i = 0; i < defs.length; i++) {
      const d = defs[i];
      const u = THREE.MathUtils.clamp(curU, u0of(d), U_END);
      markers[i].position.copy(pathPoint(d, u, _tmp));
      markers[i].visible = show;
    }
  }
})();
// @FIGURE_CODE_END

