const BOX_W = 5, BOX_H = 8;
const HW = BOX_W / 2, HH = BOX_H / 2;
const LAYER_Y = [-1.6, 0.0, 1.6];
const STEP_Y = [-4, -1.6, 0.0, 1.6, 4];

const root = new THREE.Group();
scene.add(root);

/* ── tube helper (gives real, heavy line weight) ────────────────────────── */
function tube(a, b, r, mat, parent) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 10), mat);
  m.position.copy(a).add(b).multiplyScalar(0.5);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  (parent || root).add(m);
  return m;
}
const V = (x, y, z) => new THREE.Vector3(x, y, z);

/* ── box wireframe: 12 heavy black edges ────────────────────────────────── */
const blackMat = new THREE.MeshBasicMaterial({ color: 0x000000 });
const boxGroup = new THREE.Group();
root.add(boxGroup);
const cor = [[-HW, -HW], [HW, -HW], [HW, HW], [-HW, HW]];
for (let i = 0; i < 4; i++) {
  const j = (i + 1) % 4;
  tube(V(cor[i][0], -HH, cor[i][1]), V(cor[j][0], -HH, cor[j][1]), 0.035, blackMat, boxGroup);
  tube(V(cor[i][0], HH, cor[i][1]), V(cor[j][0], HH, cor[j][1]), 0.035, blackMat, boxGroup);
  tube(V(cor[i][0], -HH, cor[i][1]), V(cor[i][0], HH, cor[i][1]), 0.035, blackMat, boxGroup);
}
boxGroup.children.forEach(ed => registerInteractive(ed, {
