/* ── path definition: Catmull-Rom over 5 height keys (wide fan, crossings) ─ */
function cr(p0, p1, p2, p3, t) {
  return 0.5 * ((2 * p1) + (-p0 + p2) * t +
    (2 * p0 - 5 * p1 + 4 * p2 - p3) * t * t +
    (-p0 + 3 * p1 - 3 * p2 + p3) * t * t * t);
}
function interp(arr, u) {
  const n = arr.length - 1;
  const f = THREE.MathUtils.clamp(u, 0, 1) * n;
  let i = Math.floor(f); if (i >= n) i = n - 1;
  const t = f - i;
  return cr(arr[Math.max(i - 1, 0)], arr[i], arr[i + 1], arr[Math.min(i + 2, n)], t);
}

const defs = [
  // three black starts low near the Data face: left / center / right
  { y0: -3.0, col: 0x111111,
    xs: [-1.90, -1.50, -0.90, -0.10, 0.60], zs: [0.60, 0.20, -0.20, -0.50, -0.70] },
  { y0: -3.4, col: 0x111111,
    xs: [0.05, -0.40, -1.10, -1.70, -2.00], zs: [-1.05, -0.60, 0.10, 0.60, 0.97] },
  { y0: -3.2, col: 0x111111,
    xs: [1.95, 1.65, 0.90, 0.10, -0.85], zs: [-0.50, -0.70, -0.30, 0.30, 0.85] },
  // two grey starts resting on the lowest interior plane (y = -1.6)
  { y0: -1.6, col: 0x6a6a6a,
