];
const CL = 2.25, U_END = (3.4 + 4) / 8;
function u0of(d) { return (d.y0 + 4) / 8; }
function pathPoint(d, u, out) {
  const x = THREE.MathUtils.clamp(interp(d.xs, u), -CL, CL);
  const z = THREE.MathUtils.clamp(interp(d.zs, u), -CL, CL);
  return (out || new THREE.Vector3()).set(x, -4 + 8 * u, z);
}
function pathTangent(d, u) {
  const a = pathPoint(d, Math.max(0, u - 0.012));
  const b = pathPoint(d, Math.min(1, u + 0.012));
  return b.sub(a).normalize();
}

const upHeads = [], downHeads = [], markers = [];
const dashMat = new THREE.MeshBasicMaterial({ color: 0x1f1f1f });
