  const N = 500, samples = [];
  for (let k = 0; k <= N; k++) samples.push(pathPoint(d, u0 + (U_END - u0) * (k / N)));
  const SPACING = 0.175;
  const dotPos = [];
  let acc = 0;
  dotPos.push(samples[0].clone());
  for (let k = 1; k <= N; k++) {
    acc += samples[k].distanceTo(samples[k - 1]);
    if (acc >= SPACING) { acc = 0; dotPos.push(samples[k].clone()); }
  }
  const inst = new THREE.InstancedMesh(dashGeo, dashMat, dotPos.length);
