    new THREE.SphereGeometry(0.12, 18, 14),
    new THREE.MeshBasicMaterial({ color: 0x262626 })
  );
  mk.visible = false;
  mk.renderOrder = 7;
  root.add(mk);
  markers.push(mk);
});

/* ── side arrows (heavy, same weight as the box edges) ──────────────────── */
function makeSideArrow(x, z, dir) {
  const mat = new THREE.MeshBasicMaterial({ color: 0x000000 });
  const g = new THREE.Group();
  const shaft = tube(V(x, dir > 0 ? -4 : -3.3, z), V(x, dir > 0 ? 3.3 : 4, z), 0.075, mat, g);
  const cap = new THREE.Mesh(new THREE.ConeGeometry(0.26, 0.78, 20), mat);
  cap.position.set(x, dir > 0 ? 3.68 : -3.68, z);
  if (dir < 0) cap.rotation.z = Math.PI;
  g.add(cap);
  g.userData = { mat };
  root.add(g);
  return g;
}
const leftArrow = makeSideArrow(-3.6, 3.6, +1);
const rightArrow = makeSideArrow(3.6, -3.6, -1);
leftArrow.children.forEach(o => registerInteractive(o, {
